CONFIGS = {
    "vendor_a": {"trains_on_customer_data": False, "retention_days": 30, "region_pinning": True},
    "vendor_b": {"trains_on_customer_data": False, "retention_days": 0, "region_pinning": False},
    "vendor_c": {"trains_on_customer_data": True, "retention_days": 90, "region_pinning": True},
}

POLICY = {"max_retention_days": 30, "allow_training": False, "require_region_pinning": True}

def check(cfg, policy):
    violations = []
    if cfg["trains_on_customer_data"] is True:
        violations.append("trains on data")
    if cfg["retention_days"] > policy["max_retention_days"]:
        violations.append("retention %s>%s" % (cfg["retention_days"], policy["max_retention_days"]))
    if cfg["region_pinning"] is False:
        violations.append("no region pinning")
    return violations

compliant_count = 0
lines = []
for vendor in ("vendor_a", "vendor_b", "vendor_c"):
    found = check(CONFIGS[vendor], POLICY)
    if found:
        lines.append(vendor + ": " + "; ".join(found))
    else:
        lines.append(vendor + ": compliant")
        compliant_count += 1
lines.append("compliant=" + str(compliant_count))
print("\n".join(lines))
